"""The living biota, region by region and habitat by habitat.

Two thirds of the present-day labels have no curated list, so their cards are
composed from the registry -- and a card that names its habitat (a desert, a
lake, a tundra, a mountain belt, an island) only reads true if the registry holds
organisms TIED to that habitat on that crust. Every entry here is a native range
and carries `hab`; that is what keeps a capuchin out of the Atacama and puts the
nerpa in Lake Baikal."""
from _lib import E, T, write
M, A, R = "Mammalia", "Aves", "Reptilia"
AN = lambda o, f, c="Magnoliopsida": (c, o, f)
D, G, F, RF, AL, TU, W, L, RV, CO, IS, ICE = ("desert", "grassland", "forest", "rainforest", "alpine", "tundra",
                                               "wetland", "lake", "river", "coast", "island", "ice")
# ---------------- deserts
E("Lama guanicoe", "species", "land", "llama", 2, 0, ["sa-s", "sa-n"], "The guanaco, wild ancestor of the llama, from sea-level Patagonian steppe to the high Atacama.", [D, G, AL], cls=(M, "Artiodactyla", "Camelidae"))
E("Copiapoa", "genus", "land", "cactus", 5, 0, ["sa-s"], "Globular cacti of the Atacama coast that live on fog: some stands see no rain for decades.", [D, CO], cls=AN("Caryophyllales", "Cactaceae"))
E("Tillandsia landbeckii", "species", "land", "bromeliad", 2, 0, ["sa-s"], "A rootless air plant forming banded 'lawns' on bare Atacama dunes, watered entirely by coastal fog.", [D], cls=AN("Poales", "Bromeliaceae", "Liliopsida"))
E("Liolaemus", "genus", "land", "lizard", 20, 0, ["sa-s", "sa-n"], "Over 250 species of small lizards from Patagonia to the high Andes -- one of the largest lizard radiations anywhere.", [D, AL, G], cls=(R, "Squamata", "Iguanidae"))
E("Rhea pennata", "species", "land", "ratite", 2, 0, ["sa-s", "sa-n"], "Darwin's rhea, the flightless runner of Patagonian steppe and Andean puna.", [G, D, AL], cls=(A, "Struthioniformes", "Rheidae"))
E("Dolichotis patagonum", "species", "land", "bigrodent", 2, 0, ["sa-s"], "The mara: a long-legged, hare-like cavy of the Patagonian scrub that pairs for life.", [D, G], cls=(M, "Rodentia", "Caviidae"))
E("Zaedyus pichiy", "species", "land", "armadillo", 2, 0, ["sa-s"], "The pichi, a small armadillo of cold Patagonian steppe and the only one known to hibernate.", [D, G], cls=(M, "Cingulata", "Dasypodidae"))
E("Larrea", "genus", "land", "shrub", 8, 0, ["sa-s", "na-w", "ca"], "Creosote bush and jarilla: resinous desert shrubs of both Americas, whose clonal rings in the Mojave are among the oldest living things.", [D], cls=AN("Zygophyllales", "Zygophyllaceae"))
E("Prosopis", "genus", "land", "acacia", 20, 0, ["sa-s", "sa-n", "na-w", "ca"], "Mesquite and algarrobo: thorny legume trees with taproots reaching tens of metres to groundwater.", [D, G], cls=AN("Fabales", "Fabaceae"))
E("Mulinum spinosum", "species", "land", "shrub", 3, 0, ["sa-s"], "Neneo, the spiny cushion shrub that dots the wind-scoured Patagonian steppe.", [D, G], cls=AN("Apiales", "Apiaceae"))
E("Camelus dromedarius", "species", "land", "camel", 2, 0, ["ar", "af-n", "af-e"], "The one-humped camel of Arabia and the Sahara, able to lose a third of its body water and drink it back in minutes.", [D], w=3, cls=(M, "Artiodactyla", "Camelidae"))
E("Oryx leucoryx", "species", "land", "antelope", 1, 0, ["ar"], "The Arabian oryx, white against the sand; extinct in the wild by 1972 and returned from captive herds.", [D], cls=(M, "Artiodactyla", "Bovidae"))
E("Gazella", "genus", "land", "antelope", 5, 0, ["ar", "af-n", "af-e", "as-w", "as-c", "in"], "Gazelles: small, fast antelopes of open arid country from Morocco to India.", [D, G], cls=(M, "Artiodactyla", "Bovidae"))
E("Uromastyx", "genus", "land", "lizard", 10, 0, ["ar", "af-n", "as-w"], "Spiny-tailed lizards: plant-eating desert agamids that block their burrows with a clubbed tail.", [D], cls=(R, "Squamata", "Agamidae"))
