E("Triodia", "genus", "land", "grass", 10, 0, ["au"], "Spinifex: needle-leaved hummock grasses covering a quarter of Australia, and shelter for most of its desert reptiles.", [D, G], cls=AN("Poales", "Poaceae", "Liliopsida"))
E("Acacia aneura", "species", "land", "acacia", 3, 0, ["au"], "Mulga, the wattle whose upswept leaves funnel rain to its own trunk; it covers a fifth of the continent.", [D], cls=AN("Fabales", "Fabaceae"))
E("Suricata suricatta", "species", "land", "carnivoran", 2, 0, ["af-s"], "The meerkat: a small mongoose of the Kalahari living in co-operative mobs with sentries.", [D, G], cls=(M, "Carnivora", "Herpestidae"))
E("Antidorcas marsupialis", "species", "land", "antelope", 2, 0, ["af-s"], "The springbok, once migrating across the Karoo and Kalahari in herds of millions.", [D, G], cls=(M, "Artiodactyla", "Bovidae"))
E("Vachellia erioloba", "species", "land", "acacia", 3, 0, ["af-s"], "The camel thorn, the Kalahari's great shade tree, rooted sixty metres down.", [D, G], cls=AN("Fabales", "Fabaceae"))
E("Aloidendron dichotomum", "species", "land", "cactus", 3, 0, ["af-s"], "The quiver tree: a giant tree-aloe of the Namib edge, now dying back at the hot end of its range.", [D], cls=AN("Asparagales", "Asphodelaceae", "Liliopsida"))
